CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, role text NOT NULL DEFAULT 'reader' CHECK(role IN ('reader','admin')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, token text NOT NULL UNIQUE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, ip_address text, user_agent text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,account_id));
CREATE TABLE IF NOT EXISTS verifications (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, bio text NOT NULL DEFAULT '', view text NOT NULL DEFAULT 'grid' CHECK(view IN ('grid','shelf')));
CREATE TABLE IF NOT EXISTS books (id text PRIMARY KEY, slug text NOT NULL UNIQUE, title text NOT NULL, author text NOT NULL, year integer NOT NULL, genre text NOT NULL, moods jsonb NOT NULL, description text NOT NULL, color text NOT NULL, ink text NOT NULL, motif text NOT NULL, featured boolean NOT NULL DEFAULT false, available boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS book_editions (id text PRIMARY KEY, book_id text NOT NULL REFERENCES books(id) ON DELETE CASCADE, label text NOT NULL, format text NOT NULL, language text NOT NULL, identifier text, pages integer CHECK(pages > 0), UNIQUE(id,book_id));
CREATE TABLE IF NOT EXISTS curated_lists (id text PRIMARY KEY, title text NOT NULL, subtitle text NOT NULL, description text NOT NULL, books jsonb NOT NULL, color text NOT NULL);
CREATE TABLE IF NOT EXISTS shelf_entries (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, book_id text NOT NULL REFERENCES books(id), status text NOT NULL CHECK(status IN ('want','reading','read')), favorite boolean NOT NULL DEFAULT false, paused boolean NOT NULL DEFAULT false, edition_id text REFERENCES book_editions(id), progress integer NOT NULL DEFAULT 0 CHECK(progress >= 0), progress_mode text NOT NULL DEFAULT 'percentage' CHECK(progress_mode IN ('percentage','pages')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,book_id), FOREIGN KEY(edition_id,book_id) REFERENCES book_editions(id,book_id), CHECK(progress_mode != 'percentage' OR progress <= 100), CHECK(NOT paused OR status = 'reading'));
CREATE TABLE IF NOT EXISTS journal_entries (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, book_id text REFERENCES books(id), title text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, book_id text NOT NULL REFERENCES books(id), body text NOT NULL, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), spoiler boolean NOT NULL DEFAULT false, hidden boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,book_id));
CREATE TABLE IF NOT EXISTS review_reports (id text PRIMARY KEY, review_id text NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, reason text NOT NULL, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,review_id));
CREATE TABLE IF NOT EXISTS moderation_actions (id text PRIMARY KEY, admin_id text REFERENCES users(id) ON DELETE SET NULL, review_id text REFERENCES reviews(id) ON DELETE SET NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS journal_owner ON journal_entries(user_id);
CREATE INDEX IF NOT EXISTS review_book_visible ON reviews(book_id,hidden);
CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);
